1	import { redirect } from "next/navigation";
2	import { getCurrentUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { getBalance, averageBuildCredits, estimateCredits } from "@/lib/credits";
5	import Editor from "./Editor";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function ProjectPage({ params }: { params: Promise<{ id: string }> }) {
10	  const user = await getCurrentUser();
11	  if (!user) redirect("/login");
12	  const { id } = await params;
13	
14	  const project = await db.project.findFirst({
15	    where: { id, userId: user.id },
16	    include: {
17	      files: { where: { published: false, kind: "source" } },
18	      messages: { orderBy: { createdAt: "asc" } },
19	    },
20	  });
21	  if (!project) redirect("/dashboard");
22	
23	  const [balance, avgBuildCredits, measuredBuilds] = await Promise.all([
24	    getBalance(user.id),
25	    averageBuildCredits(user.id),
26	    // averageBuildCredits() falls back to a global constant for someone with no
27	    // history, so on its own it cannot be described to the user as "your"
28	    // average. This count is the gate that decides whether it can — the same
29	    // gate app/dashboard/billing/page.tsx uses for its "Your average build" tile.
30	    db.build.count({
31	      where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
32	    }),
33	  ]);
34	
35	  return (
36	    <Editor
37	      projectId={project.id}
38	      projectName={project.name}
39	      slug={project.slug}
40	      published={!!project.publishedAt}
41	      initialFiles={Object.fromEntries(project.files.map((f) => [f.path, f.content]))}
42	      initialMessages={project.messages.map((m) => ({ role: m.role, content: m.content }))}
43	      initialBalance={balance}
44	      avgBuildCredits={avgBuildCredits}
45	      measuredBuilds={measuredBuilds}
46	      // Resolved here rather than in the client: lib/credits.ts reaches for
47	      // Prisma at module scope, so it can never be imported from Editor.tsx.
48	      estimates={{ create: estimateCredits("create"), edit: estimateCredits("edit") }}
49	    />
50	  );
51	}
