const el = document.getElementById('log');
const log = (m) => { el.textContent += m + "\\n"; };
const f = document.getElementById('f');

window.addEventListener('message', (e) => {
  log('RECV sameSource=' + (e.source === f.contentWindow) +
      ' origin=' + JSON.stringify(e.origin) +
      ' data=' + JSON.stringify(e.data));
});

f.addEventListener('load', () => {
  try { log('PARENT contentDocument = ' + String(f.contentDocument)); }
  catch (err) { log('PARENT contentDocument THREW ' + err.name); }
  try { log('PARENT contentWindow = ' + (f.contentWindow ? 'present (opaque proxy)' : 'null')); }
  catch (err) { log('PARENT contentWindow THREW ' + err.name); }
  try { void f.contentWindow.location.href; log('PARENT read child location = OK (BAD!)'); }
  catch (err) { log('PARENT read child location THREW ' + err.name + ' (expected)'); }
  try { void f.contentWindow.document; log('PARENT read child document = OK (BAD!)'); }
  catch (err) { log('PARENT read child document THREW ' + err.name + ' (expected)'); }

  try { f.contentWindow.postMessage({ k: 'star' }, '*'); log('PARENT sent targetOrigin="*"'); }
  catch (err) { log('PARENT star THREW ' + err.name); }
  try { f.contentWindow.postMessage({ k: 'exact-origin' }, location.origin); log('PARENT sent targetOrigin=' + location.origin + ' (delivery unknown)'); }
  catch (err) { log('PARENT exact-origin THREW ' + err.name); }
  try { f.contentWindow.postMessage({ k: 'null-origin' }, 'null'); log('PARENT sent targetOrigin="null"'); }
  catch (err) { log('PARENT null-origin THREW ' + err.name); }

  // Can the parent focus the frame / drive it with synthetic events?
  try { f.focus(); log('PARENT f.focus() ok'); } catch (err) { log('PARENT focus THREW ' + err.name); }
  try { const r = f.getBoundingClientRect(); log('PARENT frame rect = ' + Math.round(r.width) + 'x' + Math.round(r.height)); } catch (err) {}
