send({ t: 'ready', origin: location.origin, href: location.href, hasParent: parent !== window });

window.addEventListener('message', (e) => {
  if (e.source === window) return;
  send({ t: 'child-received', origin: e.origin, srcIsParent: e.source === parent, data: e.data });
});

function describe(el) {
  const path = [];
  let n = el;
  while (n && n.nodeType === 1 && n !== document.body) {
    let seg = n.tagName.toLowerCase();
    if (n.id) { seg += '#' + n.id; path.unshift(seg); break; }
    const sibs = Array.from(n.parentNode ? n.parentNode.children : []).filter(s => s.tagName === n.tagName);
    if (sibs.length > 1) seg += ':nth-of-type(' + (sibs.indexOf(n) + 1) + ')';
    path.unshift(seg);
    n = n.parentElement;
  }
  return { tag: el.tagName.toLowerCase(), id: el.id || null, cls: el.className || null,
           text: (el.textContent || '').trim().slice(0, 60), path: path.join(' > ') };
}

document.addEventListener('click', (e) => { send({ t: 'click', el: describe(e.target) }); }, true);
document.addEventListener('keydown', (e) => { send({ t: 'keydown', key: e.key, target: describe(e.target).tag }); }, true);

// prove the click path fires, without needing a real mouse
setTimeout(() => { document.getElementById('cta').click(); }, 300);
setTimeout(() => { document.querySelector('#hero h1').click(); }, 500);
setTimeout(() => {
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
}, 700);
// can the child change its own visual state (overlay drawing)?
setTimeout(() => {
  const box = document.createElement('div');
