import { createServer } from "node:http";

const SANDBOX_CSP =
  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";

// Four variants, all sandboxed "allow-scripts allow-forms" + real CSP.
// Markup is EXACTLY what Vite emits (crossorigin on both link and script)
// except where noted.
//   v1 = vite markup (crossorigin), no CORS headers      <- today's kodely-prod
//   v2 = vite markup (crossorigin), ACAO: *              <- what a fix would send
//   v3 = crossorigin attrs STRIPPED, no CORS headers     <- alternative fix
//   v4 = vite markup, ACAO: null
const VARIANTS = ["v1", "v2", "v3", "v4"];

const PARENT = `<!doctype html><html><body>
<pre id="log">START
</pre>
${VARIANTS.map((v) => `<iframe id="${v}" sandbox="allow-scripts allow-forms" src="/${v}/index.html" style="width:400px;height:120px"></iframe>`).join("\n")}
<script>
const el = document.getElementById('log');
const log = (m) => { el.textContent += m + "\\n"; };
const frames = {};
${VARIANTS.map((v) => `frames['${v}'] = document.getElementById('${v}');`).join("\n")}
window.addEventListener('message', (e) => {
  let w = 'UNKNOWN';
  for (const k in frames) if (e.source === frames[k].contentWindow) w = k;
  log('RECV[' + w + '] ' + JSON.stringify(e.data));
});
for (const k in frames) {
  frames[k].addEventListener('load', () => {
    try { frames[k].contentWindow.postMessage({ cmd: 'report' }, '*'); } catch (err) { log(k + ' send THREW ' + err.name); }
  });
}
setTimeout(() => log('END'), 5000);
</script></body></html>`;

const page = (v) => {
  const co = v === "v3" ? "" : " crossorigin";
  return `<!doctype html><html><head>
<link rel="stylesheet"${co} href="/${v}/assets/app.css">
</head><body style="margin:0">
<h1>Welcome to Acme</h1>
<script type="module"${co} src="/${v}/assets/app.js"></script>
<script>
const send = (o) => { try { parent.postMessage(Object.assign({ v: '${v}' }, o), '*'); } catch (e) {} };
window.addEventListener('message', (e) => {
  if (e.source === window || !e.data || e.data.cmd !== 'report') return;
  send({
    moduleScriptRan: document.body.dataset.moduleRan === '1',
    cssApplied: getComputedStyle(document.querySelector('h1')).color,
  });
});
</script></body></html>`;
};

const APP_JS = `document.body.dataset.moduleRan = '1';`;
const APP_CSS = `h1{color:rgb(1, 2, 3)}`;

createServer((req, res) => {
  const url = req.url.split("?")[0];
  if (url === "/" || url === "/verify.html") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" });
    return res.end(PARENT);
  }
  const m = url.match(/^\/(v[1-4])\/(.+)$/);
  if (m) {
    const [, v, rest] = m;
    const h = (type) => {
      const o = { "Content-Type": type, "Content-Security-Policy": SANDBOX_CSP, "Cache-Control": "no-store" };
      if (v === "v2") o["Access-Control-Allow-Origin"] = "*";
      if (v === "v4") o["Access-Control-Allow-Origin"] = "null";
      return o;
    };
    if (rest === "index.html") { res.writeHead(200, h("text/html; charset=utf-8")); return res.end(page(v)); }
    if (rest === "assets/app.js") { res.writeHead(200, h("text/javascript; charset=utf-8")); return res.end(APP_JS); }
    if (rest === "assets/app.css") { res.writeHead(200, h("text/css; charset=utf-8")); return res.end(APP_CSS); }
  }
  res.writeHead(404).end("nope");
}).listen(4714, () => console.log("verify2 on http://localhost:4714"));

