186	  async function send(overrideText?: string, image?: string) {
187	    const text = (overrideText ?? prompt).trim();
188	    if (!text || busy) return;
189	    if (balance <= 0) {
190	      setError("You're out of credits. Top up to keep building.");
191	      return;
192	    }
193	
194	    setBusy(true);
195	    setError(null);
196	    setInterruption(null);
197	    setWroteFiles(false);
198	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
199	    setMessages((m) => [...m, { role: "user", content: text }]);
200	    setPrompt("");
201	    setEnhancedFrom(null);
202	    streamingReply.current = "";
203	    stopRequested.current = false;
204	    const controller = new AbortController();
205	    abortRef.current = controller;
206	
207	    // Set once the first byte of the stream lands. After that point any
208	    // failure is the connection, not the request — which is what lets us tell
209	    // "couldn't start" apart from "died halfway".
210	    let streamStarted = false;
211	    // A `done` or `error` event. The route always sends one of them unless it
212	    // saw the client go away, so a stream that closes without either IS the
213	    // signature of a dropped connection.
214	    let sawTerminal = false;
215	    let touchedFiles = false;
216	
217	    try {
218	      const res = await fetch("/api/generate", {
219	        method: "POST",
220	        headers: { "Content-Type": "application/json" },
221	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
222	        signal: controller.signal,
223	      });
224	
225	      if (!res.ok || !res.body) {
226	        const body = await res.json().catch(() => ({}));
227	        throw new Error(body?.error ?? "The build failed to start.");
228	      }
229	
230	      const reader = res.body.getReader();
231	      const decoder = new TextDecoder();
232	      let buffer = "";
233	
234	      while (true) {
235	        const { done, value } = await reader.read();
236	        if (done) break;
237	        streamStarted = true;
238	        buffer += decoder.decode(value, { stream: true });
239	
240	        const parts = buffer.split("\n\n");
241	        buffer = parts.pop() ?? "";
242	
243	        for (const part of parts) {
244	          if (!part.startsWith("data: ")) continue;
245	          const event = JSON.parse(part.slice(6));
246	
247	          if (event.type === "text") {
248	            streamingReply.current += event.text;
249	          } else if (event.type === "progress" || event.type === "status") {
250	            // Both drive the same line. `progress` comes from a real tool call,
251	            // `status` from a phase the route knows about (a repair pass).
252	            setStatus(event.text);
253	          } else if (event.type === "file") {
254	            // On the SDK engine these all arrive at once after the build, so
255	            // they are a completion signal, not live progress — the progress
256	            // line above is what the user actually watches. On the `api`
257	            // engine they arrive one per write, which is what makes them
258	            // usable as evidence that a stopped build left files behind.
259	            touchedFiles = true;
260	            setWroteFiles(true);
261	          } else if (event.type === "done") {
262	            sawTerminal = true;
263	            setBalance(event.remaining);
264	            setStatus(null);
265	            setLastBuildId(event.buildId ?? null);
266	          } else if (event.type === "error") {
267	            sawTerminal = true;
268	            throw new BuildServerError(event.message);
269	          }
270	        }
271	      }
272	
273	      if (!sawTerminal) {
274	        // The pipe closed mid-build. Nothing was thrown, no error arrived —
275	        // this is exactly the silent stop the user used to be left staring at.
276	        setInterruption("connection-lost");
277	      } else if (streamingReply.current.trim()) {
278	        // Only on a build that actually completed: the route persists the
279	        // assistant reply in the success branch alone, so showing it after an
280	        // interruption would put a message on screen that a reload deletes.
281	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
282	      }
283	      // Deliberately swallowed. This runs AFTER the stream has closed cleanly,
284	      // so the build is already over and its outcome already decided — letting
285	      // a failed re-fetch fall into the catch below would report a finished
286	      // build as a lost connection, which is the one thing that block must
287	      // never say wrongly. A stale file list is a reload away; a false
288	      // "connection lost" sends the user hunting for a problem that isn't
289	      // there.
290	      if (touchedFiles) await refreshFiles().catch(() => {});
291	    } catch (err) {
292	      if (stopRequested.current) {
293	        setInterruption("stopped");
294	        // Files the agent wrote before the abort are already committed to the
295	        // draft source, so pull them in — the Code view should show what is
296	        // really there, half-finished or not.
297	        if (touchedFiles) await refreshFiles().catch(() => {});
298	      } else if (err instanceof BuildServerError) {
299	        setError(err.message);
300	      } else if (streamStarted) {
301	        setInterruption("connection-lost");
302	      } else {
303	        setError(err instanceof Error ? err.message : "Something went wrong.");
304	      }
305	    } finally {
306	      abortRef.current = null;
307	      stopRequested.current = false;
308	      setStopping(false);
309	      setBusy(false);
310	      setStatus(null);
311	    }
312	  }
