326	  // Goes through fetch rather than a plain download link so a failure lands in
327	  // the same error strip as everything else here, instead of silently saving
328	  // the JSON error body as "slug.zip".
329	  async function downloadZip() {
330	    setDownloading(true);
331	    setError(null);
332	    try {
333	      const res = await fetch(`/api/projects/${props.projectId}/export`);
334	      if (!res.ok) {
335	        const body = await res.json().catch(() => ({}));
336	        throw new Error(body?.error ?? "Download failed.");
337	      }
338	      const url = URL.createObjectURL(await res.blob());
339	      const link = document.createElement("a");
340	      link.href = url;
341	      link.download = `${props.slug}.zip`;
342	      link.click();
343	      // The click hands the blob off asynchronously, so revoking in the same
344	      // tick can cancel the download in some browsers. Next tick is enough,
345	      // and skipping the revoke entirely would pin the archive in memory for
346	      // the life of the tab.
347	      setTimeout(() => URL.revokeObjectURL(url), 0);
348	    } catch (err) {
349	      setError(err instanceof Error ? err.message : "Download failed.");
350	    } finally {
351	      setDownloading(false);
352	    }
353	  }
