393	  // Global shortcuts. Deliberately three, all of them either an established
394	  // convention (⌘K / ⌃⇧P for a palette, "/" to jump to the input) or a
395	  // disambiguation of a key the box already owns (⌘⏎ builds even when Enter
396	  // has been handed over to the spec editor). Anything more inventive would
397	  // be a shortcut nobody discovers and everybody triggers by accident.
398	  // Bound only while the palette is CLOSED. While it is open the dialog owns
399	  // the keyboard outright — that is what makes the focus trap and the Escape
400	  // handling airtight, and it saves reading a "is it open" ref during render.
401	  useEffect(() => {
402	    if (paletteOpen) return;
403	    function onKeyDown(e: KeyboardEvent) {
404	      const mod = e.metaKey || e.ctrlKey;
405	      const openWith = (opener: HTMLElement | null) => {
406	        paletteReturn.current = opener;
407	        setPaletteOpen(true);
408	      };
409	      const active = document.activeElement;
410	      const focused = active instanceof HTMLElement && active !== document.body ? active : null;
411	
412	      if (mod && !e.altKey && e.key.toLowerCase() === "k") {
413	        e.preventDefault();
414	        openWith(focused);
415	        return;
416	      }
417	      if (mod && e.shiftKey && e.key.toLowerCase() === "p") {
418	        e.preventDefault();
419	        openWith(focused);
420	        return;
421	      }
422	      if (e.key === "/" && !mod && !e.altKey) {
423	        // "/" is a normal character inside a field — only a jump-to-input
424	        // shortcut when the user isn't already typing somewhere.
425	        const typing =
426	          focused !== null &&
427	          (focused.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(focused.tagName));
428	        if (typing) return;
429	        e.preventDefault();
430	        promptRef.current?.focus();
431	      }
432	    }
433	    window.addEventListener("keydown", onKeyDown);
434	    return () => window.removeEventListener("keydown", onKeyDown);
435	  }, [paletteOpen]);
