import { createServer } from "node:http";

const SANDBOX_CSP =
  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";

// Does a SameSite=Lax session cookie ride along on requests made FROM a
// sandboxed opaque-origin iframe?  This decides whether the preview can load
// ANY subresource from a cookie-authenticated route, or whether everything has
// to be inlined into the HTML document.
const log = [];

const PARENT = `<!doctype html><html><body>
<pre id="log">START
</pre>
<iframe id="f" sandbox="allow-scripts allow-forms" src="/preview/index.html" style="width:400px;height:100px"></iframe>
<script>
const el = document.getElementById('log');
const add = (m) => { el.textContent += m + "\\n"; };
const f = document.getElementById('f');
window.addEventListener('message', (e) => add('RECV ' + JSON.stringify(e.data)));
f.addEventListener('load', () => setTimeout(() => {
  fetch('/serverlog').then(r => r.json()).then(rows => {
    for (const r of rows) add('SERVER ' + r);
  });
}, 800));
setTimeout(() => add('END'), 4000);
</script></body></html>`;

const PREVIEW = `<!doctype html><html><head>
<link rel="stylesheet" href="/preview/assets/app.css">
</head><body style="margin:0">
<h1>Hi</h1>
<img id="pic" src="/preview/assets/pic.gif" alt="p">
<script>
const send = (o) => { try { parent.postMessage(o, '*'); } catch (e) {} };
setTimeout(() => {
  send({ cssColor: getComputedStyle(document.querySelector('h1')).color,
         imgOk: document.getElementById('pic').complete && document.getElementById('pic').naturalWidth > 0 });
}, 500);
</script></body></html>`;

const GIF = Buffer.from("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7", "base64");

createServer((req, res) => {
  const url = req.url.split("?")[0];
  const cookie = req.headers.cookie ?? "<none>";
  const secFetchSite = req.headers["sec-fetch-site"] ?? "-";
  if (url !== "/serverlog") {
    log.push(`${url}  cookie=${cookie}  sec-fetch-site=${secFetchSite} origin=${req.headers.origin ?? "-"}`);
  }
  if (url === "/serverlog") {
    res.writeHead(200, { "Content-Type": "application/json" });
    return res.end(JSON.stringify(log));
  }
  if (url === "/" || url === "/verify.html") {
    res.writeHead(200, {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
      "Set-Cookie": "kodely_session=abc123; Path=/; HttpOnly; SameSite=Lax",
    });
    return res.end(PARENT);
  }
  const h = (type) => ({ "Content-Type": type, "Content-Security-Policy": SANDBOX_CSP, "Cache-Control": "no-store" });
  if (url === "/preview/index.html") { res.writeHead(200, h("text/html; charset=utf-8")); return res.end(PREVIEW); }
  if (url === "/preview/assets/app.css") { res.writeHead(200, h("text/css; charset=utf-8")); return res.end("h1{color:rgb(9, 9, 9)}"); }
  if (url === "/preview/assets/pic.gif") { res.writeHead(200, h("image/gif")); return res.end(GIF); }
  res.writeHead(404).end("nope");
}).listen(4715, () => console.log("verify3 on http://localhost:4715"));

import { createServer } from "node:http";

// Candidate design: keep sandbox="allow-scripts allow-forms" (unchanged), but
// hand the iframe a SELF-CONTAINED document via srcdoc, with the security
// policy re-asserted in-band by <meta http-equiv>.
const META_CSP =
  "default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; form-action 'none'; base-uri 'none'; object-src 'none'";

const serverHits = [];

const SRCDOC = `<!doctype html><html><head>
<meta http-equiv="Content-Security-Policy" content="${META_CSP}">
<meta charset="UTF-8">
<title>Generated site</title>
<style>h1{color:rgb(7,7,7)} body{margin:0;font-family:system-ui}</style>
</head><body>
<section id="hero"><h1>Welcome to Acme</h1><p>Copy here</p><button id="cta">Go</button></section>
<img id="dataimg" src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7" alt="d">
<script type="module">
  document.body.dataset.moduleRan = '1';
<\/script>
<script src="http://localhost:4716/should-be-blocked.js"><\/script>
<script>
  const send = (o) => { try { parent.postMessage(Object.assign({ ns:'k' }, o), '*'); } catch (e) {} };
  send({ t:'ready' });
  window.addEventListener('message', (e) => {
    if (e.source === window || !e.data || e.data.cmd !== 'report') return;
    document.getElementById('cta').click();
    const probe = { t:'REPORT',
      srcIsParent: e.source === parent, msgOrigin: e.origin,
      selfOrigin: location.origin, href: location.href, baseURI: document.baseURI,
      moduleRan: document.body.dataset.moduleRan === '1',
      h1Color: getComputedStyle(document.querySelector('h1')).color,
      dataImgOk: (() => { const i = document.getElementById('dataimg'); return i.complete && i.naturalWidth > 0; })(),
      externalScriptRan: typeof window.__EXTERNAL_RAN !== 'undefined',
      clicks: window.__clicks || [],
    };
    fetch('http://localhost:4716/should-be-blocked-fetch')
      .then(() => { probe.fetchBlocked = false; send(probe); })
      .catch((err) => { probe.fetchBlocked = true; probe.fetchErr = String(err.message); send(probe); });
  });
  window.__clicks = [];
  document.addEventListener('click', (e) => { window.__clicks.push(e.target.tagName + '#' + e.target.id); }, true);
<\/script>
</body></html>`;

const PARENT = `<!doctype html><html><body>
<pre id="log">START
</pre>
<iframe id="f" sandbox="allow-scripts allow-forms" style="width:400px;height:200px"></iframe>
<script>
const el = document.getElementById('log');
const add = (m) => { el.textContent += m + "\\n"; };
const f = document.getElementById('f');
window.addEventListener('message', (e) => {
  add('RECV sameSource=' + (e.source === f.contentWindow) + ' origin=' + JSON.stringify(e.origin) + ' ' + JSON.stringify(e.data));
});
f.addEventListener('load', () => {
  if (!f.srcdoc) return;
  try { add('contentDocument=' + String(f.contentDocument)); } catch (err) { add('contentDocument THREW ' + err.name); }
  try { f.contentWindow.postMessage({ cmd:'report' }, '*'); add('sent report'); } catch (err) { add('send THREW ' + err.name); }
});
f.srcdoc = ${JSON.stringify(SRCDOC)};
setTimeout(() => {
  fetch('/serverhits').then(r=>r.json()).then(rows => { add('SERVER SAW: ' + JSON.stringify(rows)); });
}, 2500);
setTimeout(() => add('END'), 5000);
</script></body></html>`;

createServer((req, res) => {
  const url = req.url.split("?")[0];
  if (url !== "/serverhits" && url !== "/" && url !== "/verify.html") serverHits.push(url);
  if (url === "/serverhits") { res.writeHead(200, { "Content-Type": "application/json" }); return res.end(JSON.stringify(serverHits)); }
  if (url === "/should-be-blocked.js") { res.writeHead(200, { "Content-Type": "text/javascript" }); return res.end("window.__EXTERNAL_RAN=1;"); }
  if (url === "/should-be-blocked-fetch") { res.writeHead(200, { "Access-Control-Allow-Origin": "*" }); return res.end("ok"); }
  res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" });
  res.end(PARENT);
}).listen(4716, () => console.log("verify4 on http://localhost:4716"));

