"use client";

import type { RefObject } from "react";

// The preview pane, plus the width switcher and the click-to-select toggle
// above it.
//
// Generated sites are prompted to hold up down to 380px, and until now there
// was no way to check that without publishing and opening the result on a
// phone. So: three widths, a real pixel number next to them, and nothing else.
// No rounded phone shell, no notch, no rotate button — a device chrome would
// imply we are emulating a device, and we are not. We are changing a width.
//
// The iframe is fed a SELF-CONTAINED document through `srcdoc` rather than
// pointed at a URL. See the long note at the top of preview-agent.ts for why:
// in short, every subresource request made from inside this frame is treated
// as cross-site and arrives without the session cookie, so a preview built out
// of separate asset requests cannot load at all. Inlining is what makes the
// preview render, and it is also what gives us somewhere to put the selection
// agent. The `sandbox` attribute below is UNCHANGED and must stay that way —
// adding `allow-same-origin` would hand generated customer code the parent
// origin.
//
// The iframe element is deliberately NOT re-keyed when the width changes, so
// switching widths resizes the live page rather than reloading it. That is the
// difference between testing a responsive layout and testing a page load.

export type DeviceId = "desktop" | "tablet" | "mobile";

export const DEVICES: { id: DeviceId; label: string; width: number | null; note: string }[] = [
  { id: "desktop", label: "Desktop", width: null, note: "full width" },
  { id: "tablet", label: "Tablet", width: 768, note: "768px" },
  // 380 rather than a real handset width: it is the floor the site generator
  // is told to support, so it is the number worth testing against.
  { id: "mobile", label: "Mobile", width: 380, note: "380px" },
];

const FOCUS_RING =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";

export default function PreviewFrame({
  doc,
  loading,
  error,
  reloadKey,
  device,
  onDeviceChange,
  frameRef,
  selectMode,
  selectAvailable,
  onToggleSelectMode,
}: {
  /** The assembled document, or null before the first load finishes. */
  doc: string | null;
  loading: boolean;
  error: string | null;
  reloadKey: number;
  device: DeviceId;
  onDeviceChange: (device: DeviceId) => void;
  frameRef: RefObject<HTMLIFrameElement | null>;
  selectMode: boolean;
  /** The preview answered the handshake, so the toggle can do something. */
  selectAvailable: boolean;
  onToggleSelectMode: () => void;
}) {
  const active = DEVICES.find((d) => d.id === device) ?? DEVICES[0];

  return (
    <div className="flex h-full flex-col">
      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-black/10 px-3 py-2 dark:border-white/10">
        <div className="flex flex-wrap items-center gap-2">
          <div
            role="group"
            aria-label="Preview width"
            className="flex items-center gap-1 rounded-lg border border-black/10 p-0.5 text-xs dark:border-white/10"
          >
            {DEVICES.map((d) => (
              <button
                key={d.id}
                type="button"
                onClick={() => onDeviceChange(d.id)}
                aria-pressed={device === d.id}
                className={`rounded-md px-2 py-1 ${FOCUS_RING} ${
                  device === d.id
                    ? "bg-black text-white dark:bg-white dark:text-black"
                    : "text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
                }`}
              >
                {d.label}
              </button>
            ))}
          </div>

          {/* Disabled until the preview has actually answered. A toggle that
              looks live but cannot target anything is worse than no toggle. */}
          <button
            type="button"
            onClick={onToggleSelectMode}
            aria-pressed={selectMode}
            disabled={!selectAvailable}
            title={
              selectAvailable
                ? "Click an element in the preview to refer to it in your next change"
                : "Available once the preview has loaded"
            }
            className={`rounded-lg border px-2 py-1 text-xs disabled:opacity-40 ${FOCUS_RING} ${
              selectMode
                ? "border-black bg-black text-white dark:border-white dark:bg-white dark:text-black"
                : "border-black/10 text-black/60 hover:text-black dark:border-white/10 dark:text-white/60 dark:hover:text-white"
            }`}
          >
            Select element
          </button>
        </div>

        {/* The number matters more than the label — "Mobile" is a guess,
            "380px" is a fact you can compare a bug report against. */}
        <span className="text-xs text-black/40 dark:text-white/40">
          Preview at {active.note}
        </span>
      </div>

      {/* Constrained widths keep their real pixel size and let this container
          scroll if the pane is narrower — clamping them to the pane would
          make the "768px" label a lie, which is the one thing this control
          cannot afford. The scroll is contained here, never on the page. */}
      <div className="flex min-h-0 flex-1 justify-center overflow-auto">
        {error ? (
          <p className="m-auto max-w-sm px-6 text-center text-sm text-black/60 dark:text-white/60">
            {error}
          </p>
        ) : doc === null ? (
          <p className="m-auto px-6 text-sm text-black/45 dark:text-white/45">
            {loading ? "Loading preview…" : "Nothing to preview yet."}
          </p>
        ) : (
          <iframe
            key={reloadKey}
            ref={frameRef}
            srcDoc={doc}
            sandbox="allow-scripts allow-forms"
            title={`Live preview at ${active.note}`}
            style={active.width ? { width: active.width } : undefined}
            className={`h-full shrink-0 bg-white ${
              active.width
                ? "border-x border-black/10 dark:border-white/10"
                : "w-full border-0"
            }`}
          />
        )}
      </div>
    </div>
  );
}

