// End-to-end harness for click-to-select.
//
// Serves the REAL build output of a real generated project through a stand-in
// for app/api/preview/[id]/[[...path]]/route.ts (same CSP header, same paths),
// and a stand-in for the editor page that uses the REAL preview-agent.ts
// (type-stripped by Node, served as a browser module).
//
// Nothing here is a mock of the thing under test: buildPreviewDocument,
// normalizeSelection, selectionReference and the injected agent are the actual
// shipping code.

import { createServer } from "node:http";
import { readFileSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";

const SCRATCH = "C:/Users/edmem/AppData/Local/Temp/claude/C--Users-edmem-OneDrive-Desktop-Kodely/eb67eaec-3d5e-420f-a5fc-4419d7203aa9/scratchpad";
const AGENT_TS = "C:/Users/edmem/kodely-prod/app/projects/[id]/preview-agent.ts";

const BUILD = JSON.parse(readFileSync(`${SCRATCH}/build-files.json`, "utf8"));
const AGENT_JS = stripTypeScriptTypes(readFileSync(AGENT_TS, "utf8"), { mode: "strip" });

const PID = "test-project";

// Byte-identical to SANDBOX_CSP in the real preview route.
const SANDBOX_CSP =
  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";

const MIME = { html: "text/html; charset=utf-8", css: "text/css; charset=utf-8", js: "text/javascript; charset=utf-8" };

// Mirrors what Editor.tsx does, using the real exported functions.
const EDITOR = `<!doctype html><html><body style="margin:0">
<pre id="log" style="font:11px monospace;margin:0;height:120px;overflow:auto">START
</pre>
<iframe id="f" sandbox="allow-scripts allow-forms"
        style="width:900px;height:600px;border:0;display:block"></iframe>
<script type="module">
import { PREVIEW_NS, buildPreviewDocument, normalizeSelection, selectionReference }
  from '/preview-agent.js';

const el = document.getElementById('log');
const log = (m) => { el.textContent += m + "\\n"; window.__LOG = (window.__LOG||[]).concat(m); };
const f = document.getElementById('f');
window.__SEL = null;

const post = (msg) => {
  // targetOrigin "*" is mandatory: the frame's origin is opaque.
  f.contentWindow?.postMessage({ ...msg, ns: PREVIEW_NS }, '*');
};
window.__post = post;

window.addEventListener('message', (event) => {
  if (!event.source || event.source !== f.contentWindow) return;
  const d = event.data;
  if (!d || typeof d !== 'object' || d.ns !== PREVIEW_NS) return;
  if (d.type === 'ready') { log('READY (origin=' + JSON.stringify(event.origin) + ')'); window.__READY = true; return; }
  if (d.type === 'mode') { log('MODE ' + d.on); return; }
  if (d.type === 'cleared') { log('CLEARED'); window.__SEL = null; return; }
  if (d.type === 'selected') {
    const sel = normalizeSelection(d.el);
    if (!sel) { log('SELECTED but REJECTED by normalizeSelection'); return; }
    window.__SEL = sel;
    log('SELECTED ' + JSON.stringify({ tag: sel.tag, id: sel.id, text: sel.text, path: sel.path, section: sel.section, rect: sel.rect }));
    log('PROMPT   Change ' + selectionReference(sel) + ': ');
  }
});

const base = '/api/preview/${PID}';
(async () => {
  try {
    const res = await fetch(base + '/index.html', { cache: 'no-store' });
    log('index.html -> ' + res.status);
    const built = await buildPreviewDocument(await res.text(), async (path) => {
      const r = await fetch(base + '/' + path, { cache: 'no-store' });
      log('  asset ' + path + ' -> ' + r.status);
      return r.ok ? await r.text() : null;
    });
    log('assembled ' + built.doc.length + ' bytes, missing=' + JSON.stringify(built.missing));
    log('has meta CSP: ' + built.doc.includes('http-equiv="Content-Security-Policy"'));
    log('has external asset refs left: ' + /(src|href)="\\/assets\\//.test(built.doc));
    f.srcdoc = built.doc;
    window.__DOC = built.doc;
  } catch (err) { log('ASSEMBLY FAILED ' + err.message); }
})();

// Did the generated React app actually mount inside the frame? The parent
// cannot look, so ask the agent to select the first thing it finds.
window.__probe = () => { post({ cmd: 'set-mode', on: true }); };
<\/script></body></html>`;

createServer((req, res) => {
  const url = req.url.split("?")[0];
  if (url === "/" || url === "/editor") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" });
    return res.end(EDITOR);
  }
  if (url === "/preview-agent.js") {
    res.writeHead(200, { "Content-Type": "text/javascript; charset=utf-8", "Cache-Control": "no-store" });
    return res.end(AGENT_JS);
  }
  const m = url.match(new RegExp(`^/api/preview/${PID}/(.+)$`));
  if (m) {
    const file = BUILD[m[1]];
    if (file === undefined) { res.writeHead(404).end("Not found."); return; }
    const ext = m[1].split(".").pop();
    res.writeHead(200, {
      "Content-Type": MIME[ext] ?? "application/octet-stream",
      "Content-Security-Policy": SANDBOX_CSP,
      "Cache-Control": "no-store",
    });
    return res.end(file);
  }
  res.writeHead(404).end("nope");
}).listen(4720, () => console.log("e2e on http://localhost:4720"));

// Drives headless Chrome over CDP so we can dispatch a REAL mouse click into
// the sandboxed preview frame — the one thing --dump-dom cannot do.
const PORT = 9333;

async function targets() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
  return await res.json();
}

function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    const pending = new Map();
    let id = 0;
    ws.addEventListener("open", () =>
      resolve({
        send(method, params = {}, sessionId) {
          const msgId = ++id;
          const msg = { id: msgId, method, params };
          if (sessionId) msg.sessionId = sessionId;
          ws.send(JSON.stringify(msg));
          return new Promise((res2, rej2) => pending.set(msgId, { res2, rej2 }));
        },
        close: () => ws.close(),
      }),
    );
    ws.addEventListener("error", reject);
    ws.addEventListener("message", (e) => {
      const m = JSON.parse(e.data);
      if (m.id && pending.has(m.id)) {
        const { res2, rej2 } = pending.get(m.id);
        pending.delete(m.id);
        m.error ? rej2(new Error(JSON.stringify(m.error))) : res2(m.result);
      }
    });
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const list = await targets();
const page = list.find((t) => t.type === "page");
if (!page) throw new Error("no page target");
const cdp = await connect(page.webSocketDebuggerUrl);

const evaluate = async (expr) => {
  const r = await cdp.send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.text + " " + JSON.stringify(r.exceptionDetails.exception?.description ?? ""));
  return r.result.value;
};

await cdp.send("Page.enable");
await cdp.send("Runtime.enable");
await cdp.send("Page.navigate", { url: "http://localhost:4720/editor" });
await sleep(3500);

console.log("---- after load ----");
console.log((await evaluate("(window.__LOG||[]).join('\\n')")) || "(no log)");
console.log("ready:", await evaluate("!!window.__READY"));

// Turn on select mode through the public protocol, exactly as the toggle does.
await evaluate("window.__post({ cmd: 'set-mode', on: true })");
await sleep(400);

// --- a REAL mouse click, at real viewport coordinates over the frame --------
const box = await evaluate(
  "(() => { const r = document.getElementById('f').getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; })()",
);
// Aim a good way down the hero so we land on real generated content.
const cx = Math.round(box.x + box.w / 2);
const cy = Math.round(box.y + 160);
console.log(`---- dispatching real mouse click at (${cx}, ${cy}) over frame ${box.w}x${box.h} ----`);
for (const type of ["mouseMoved", "mousePressed", "mouseReleased"]) {
  await cdp.send("Input.dispatchMouseEvent", {
    type,
    x: cx,
    y: cy,
    button: "left",
    buttons: type === "mousePressed" ? 1 : 0,
    clickCount: type === "mouseMoved" ? 0 : 1,
  });
  await sleep(90);
}
await sleep(600);
console.log((await evaluate("(window.__LOG||[]).slice(-4).join('\\n')")) || "(nothing new)");

// --- keyboard: arrow keys inside the frame ---------------------------------
console.log("---- real ArrowUp keypress (frame has focus after the click) ----");
for (const type of ["keyDown", "keyUp"]) {
  await cdp.send("Input.dispatchKeyEvent", { type, key: "ArrowUp", code: "ArrowUp", windowsVirtualKeyCode: 38, nativeVirtualKeyCode: 38 });
  await sleep(80);
}
await sleep(500);
console.log((await evaluate("(window.__LOG||[]).slice(-2).join('\\n')")) || "(nothing new)");

// --- parent-driven movement (keyboard path from the editor's own buttons) ---
console.log("---- parent-driven move: down, next ----");
await evaluate("window.__post({ cmd: 'move', dir: 'down' })");
await sleep(350);
await evaluate("window.__post({ cmd: 'move', dir: 'next' })");
await sleep(350);
console.log((await evaluate("(window.__LOG||[]).slice(-4).join('\\n')")) || "(nothing new)");

console.log("---- Escape inside the frame should exit select mode ----");
for (const type of ["keyDown", "keyUp"]) {
  await cdp.send("Input.dispatchKeyEvent", { type, key: "Escape", code: "Escape", windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });
  await sleep(80);
}
await sleep(400);
console.log((await evaluate("(window.__LOG||[]).slice(-2).join('\\n')")) || "(nothing new)");

console.log("---- clear ----");
await evaluate("window.__post({ cmd: 'clear' })");
await sleep(300);
console.log((await evaluate("(window.__LOG||[]).slice(-1).join('\\n')")) || "(nothing new)");

console.log("---- parent isolation re-check on the live frame ----");
console.log(
  await evaluate(
    "(() => { const f = document.getElementById('f'); const out = {}; out.contentDocument = String(f.contentDocument);" +
      " try { void f.contentWindow.location.href; out.location = 'READABLE (BAD)'; } catch (e) { out.location = e.name; }" +
      " try { void f.contentWindow.document.body; out.document = 'READABLE (BAD)'; } catch (e) { out.document = e.name; }" +
      " out.sandbox = f.getAttribute('sandbox'); return JSON.stringify(out); })()",
  ),
);

cdp.close();

